<?php
namespace ScratchByPHP\Testing;
use ScratchByPHP\Collections\Collection;
final class FakeScratch { private array $projects=[],$users=[],$studios=[]; public function fakeProject(int|string $id,array $data):self{$this->projects[(string)$id]=$data+['id'=>(int)$id];return $this;} public function fakeUser(string $u,array $data):self{$this->users[$u]=$data+['username'=>$u];return $this;} public function fakeStudio(int|string $id,array $data):self{$this->studios[(string)$id]=$data+['id'=>(int)$id];return $this;} public function project(int|string $id):FakeModel{return new FakeModel($this->projects[(string)$id]??['id'=>(int)$id]);} public function user(string $u):FakeModel{return new FakeModel($this->users[$u]??['username'=>$u]);} public function studio(int|string $id):FakeModel{return new FakeModel($this->studios[(string)$id]??['id'=>(int)$id]);} }
final class FakeModel implements \JsonSerializable { public function __construct(private array $data){} public function get():array{return $this->data;} public function __call(string $name,array $args):mixed{$map=['title'=>'title','views'=>'views','loves'=>'loves','favorites'=>'favorites','username'=>'username','bio'=>'bio','country'=>'country'];$k=$map[$name]??$name;return $this->data[$k]??($this->data['stats'][$k]??null);} public function toArray():array{return $this->data;} public function jsonSerialize():mixed{return $this->data;} }
